.card {
  /* Content area */
  width: 300px;
  height: 200px;

  /* Padding — space INSIDE the border */
  padding: 24px;            /* all four sides */
  padding: 16px 24px;       /* top/bottom  left/right */
  padding: 8px 16px 24px 32px; /* top right bottom left */

  /* Border */
  border: 2px solid #4fd1c5;
  border-radius: 8px;

  /* Margin — space OUTSIDE the border */
  margin: 16px;
  margin: 0 auto;           /* centre horizontally */
}

/* Default (content-box): total width = 300 + 24 + 24 + 2 + 2 = 352px */
.default {
  width: 300px;
  padding: 24px;
  border: 2px solid;
}

/* border-box: total width = exactly 300px */
.better {
  box-sizing: border-box;
  width: 300px;
  padding: 24px;
  border: 2px solid;
}

/* Apply border-box to everything — industry standard */
*, *::before, *::after {
  box-sizing: border-box;
}

h2 { margin-bottom: 24px; }
p  { margin-top: 16px; }

/* Gap between h2 and p = 24px (not 40px) — larger wins */

